  let previous = null;
  for (const [index, event] of build.custody_chain.entries()) {
    if (event.event_index !== index + 1) errors.push(`PC-59 custody event ${index} index mismatch`);
    if (event.previous_event_sha256 !== previous) errors.push(`PC-59 custody event ${index} previous hash mismatch`);
    const { event_sha256, ...unsigned } = event;
    if (event_sha256 !== sha256(unsigned)) errors.push(`PC-59 custody event ${index} hash mismatch`);
    previous = event_sha256;
  }
  if (build.custody_chain_head_sha256 !== previous) errors.push('PC-59 custody chain head mismatch');
